  const BTN = (text, kind, icon) => `<button data-slot="button" class="group/button inline-flex shrink-0 items-center justify-center rounded-lg border ${kind === 'primary' ? 'border-transparent bg-primary text-primary-foreground' : kind === 'ghost' ? 'border-transparent' : 'border-border bg-background'} bg-clip-padding text-sm font-medium whitespace-nowrap outline-none select-none [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 h-8 gap-1.5 px-2.5">${icon ? `<i data-lucide="${icon}"></i>` : ''}${text}</button>`;
  const BTN_SM = (text, kind, icon) => `<button data-slot="button" class="group/button inline-flex shrink-0 items-center justify-center border ${kind === 'primary' ? 'border-transparent bg-primary text-primary-foreground' : kind === 'ghost' ? 'border-transparent' : 'border-border bg-background'} bg-clip-padding font-medium whitespace-nowrap outline-none select-none [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3.5 h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-2.5 text-sm">${icon ? `<i data-lucide="${icon}"></i>` : ''}${text}</button>`;
  const ICON_BTN = (icon) => `<button class="inline-flex size-8 shrink-0 items-center justify-center rounded-lg border border-border bg-background"><i data-lucide="${icon}" class="size-4"></i></button>`;
