  const TABS = (variant, items, active, list = '') => `<div data-slot="tabs" data-orientation="horizontal" data-horizontal="" class="group/tabs flex gap-2 data-horizontal:flex-col max-w-full"><div role="tablist" data-slot="tabs-list" data-orientation="horizontal" data-variant="${variant}" class="group/tabs-list inline-flex w-fit items-center rounded-lg p-[3px] text-muted-foreground group-data-horizontal/tabs:h-8 data-[variant=line]:rounded-none bg-transparent ${list}">${items.map((t, i) => `<button role="tab" data-slot="tabs-trigger" ${i === active ? 'data-active=""' : ''} class="${TT}">${t}</button>`).join('')}</div></div>`;
