  const CHK = (on) => `<span role="checkbox" data-slot="checkbox" ${on ? 'data-checked=""' : ''} class="peer relative flex size-4 shrink-0 items-center justify-center rounded-[4px] border border-input data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground">${on ? '<i data-lucide="check" class="size-3.5"></i>' : ''}</span>`;
