  // NocoReach's mark, as the product draws it
  const BARS = [{ x: 18, top: 42 }, { x: 32, top: 33 }, { x: 46, top: 21 }];
  const markSVG = (cls) => `<svg class="${cls}" viewBox="0 0 64 64"><rect x=".5" y=".5" width="63" height="63" rx="14.5" fill="#0B0B0F" stroke="#fff" stroke-opacity=".12"/>` +
    BARS.map(({ x, top }, i) => { const tp = `M${x - 7} ${top - 4}L${x} ${top - 8}L${x + 7} ${top - 4}L${x} ${top}Z`;
      return `<path d="M${x - 7} ${top - 4}L${x} ${top}V52L${x - 7} 48Z" fill="#fff"/><path d="M${x} ${top}L${x + 7} ${top - 4}V48L${x} 52Z" fill="#fff" fill-opacity=".72"/><path d="${tp}" fill="#fff" fill-opacity=".45"/>${i === 2 ? `<path d="${tp}" fill="#7C6CFF"/>` : ''}`; }).join('') + '</svg>';
  // the data sources' marks (the product's source logos)
  const LG = window.__SRC_LOGOS;
  const brand = (k, cls) => { const l = LG[k]; return `<svg viewBox="0 0 24 24" fill="currentColor" class="${cls} ${l.color ? 'text-(--brand-color)' : 'text-foreground'}" ${l.color ? `style="--brand-color:${l.color};color:${l.color}"` : ''}><path d="${l.path}"/></svg>`; };
  const mark = (m, cls) => (m.startsWith('i:') ? `<i data-lucide="${m.slice(2)}" class="${cls} text-muted-foreground"></i>` : brand(m, cls));
  const LOGO = (m, size = 'size-6', inner = 'size-4') => `<span data-slot="source-logo" class="inline-flex shrink-0 items-center justify-center ${size} rounded border bg-background">${mark(m, inner)}</span>`;

  // ------------------------------------------------------------------ the app shell
  const MENU_A = (icon, text, active, badge) => `<li data-slot="sidebar-menu-item" class="group/menu-item relative"><a data-slot="sidebar-menu-button" data-size="default" ${active ? 'data-active=""' : ''} class="peer/menu-button group/menu-button flex w-full items-center gap-2 overflow-hidden rounded-md p-2 text-left outline-hidden data-active:font-medium [&_svg]:size-4 [&_svg]:shrink-0 [&>span:last-child]:truncate h-8 text-sm data-active:bg-sidebar-primary data-active:text-sidebar-primary-foreground"><i data-lucide="${icon}"></i><span>${text}</span></a>${badge ? `<div data-slot="sidebar-menu-badge" class="pointer-events-none absolute right-1 flex h-5 min-w-5 items-center justify-center text-xs font-medium tabular-nums select-none top-1.5 rounded-full px-1.5 bg-attention text-attention-foreground">${badge}</div>` : ''}</li>`;
  const MENU_B = (icon, text, sub) => `<li class="group/menu-item relative"><button data-slot="sidebar-menu-button" data-size="default" class="peer/menu-button group/menu-button flex w-full items-center gap-2 overflow-hidden rounded-md p-2 text-left outline-hidden [&_svg]:size-4 [&_svg]:shrink-0 h-8 text-sm"><i data-lucide="${icon}"></i><span>${text}</span><i data-lucide="chevron-right" class="ml-auto${sub ? ' rotate-90' : ''}"></i></button>${sub ? `<ul data-slot="sidebar-menu-sub" class="mx-3.5 flex min-w-0 translate-x-px flex-col gap-1 border-l border-sidebar-border px-2.5 py-0.5">${sub}</ul>` : ''}</li>`;
