    const KPI = (label, value, delta, s) => `<a class="flex flex-col gap-1 rounded-lg border bg-card px-3 pt-2.5 pb-2 text-card-foreground"><span class="text-xs text-muted-foreground">${label}</span><span class="flex flex-wrap items-baseline gap-x-2"><span class="text-xl leading-7 font-medium tabular-nums sm:text-[1.375rem]">${value}</span><span class="text-xs font-medium tabular-nums text-nr-ink-green">${delta}</span></span>${spark(s, 6)}</a>`;
